.ds .ds-token-opacity i { width:var(--p-control-size-sm); height:var(--p-control-size-sm); border-radius:var(--p-inner-radius); background:var(--p-ink); opacity:var(--p-opacity-full); }
.ds .ds-token-opacity [data-token="dim"] { opacity:var(--p-opacity-dim); }
.ds .ds-token-opacity [data-token="disabled"] { opacity:var(--p-opacity-disabled); }
.ds .ds-token-opacity [data-token="faint"] { opacity:var(--p-opacity-faint); }
